"use client";

import { useRouter } from "next/navigation";

export function GmailStatus({
  connected,
  paused = false,
}: {
  connected: boolean;
  paused?: boolean;
}) {
  const router = useRouter();
  const content = (
    <>
      <span
        className="workspace-gmail-dot w-2 h-2 shrink-0 rounded-[50%] [background:var(--color-globals-color-50)] shadow-[0_0_0_4px_var(--color-globals-box-shadow-66)]"
        aria-hidden="true"
      />
      Gmail{" "}
      {paused ? "sending paused" : connected ? "connected" : "not connected"}
    </>
  );
  return connected && !paused ? (
    <span
      className="workspace-gmail inline-flex items-center shrink-0 [border:1px_solid_var(--border,_var(--color-globals-border-63))] rounded-full [background:var(--card,_var(--color-globals-background-64))] text-[var(--foreground,_var(--color-globals-color-65))] h-11 py-0 px-4 gap-2 text-[14px] whitespace-nowrap [&[data-connected='false']]:cursor-pointer"
      data-connected="true"
    >
      {content}
    </span>
  ) : (
    <button
      type="button"
      className="workspace-gmail inline-flex items-center shrink-0 [border:1px_solid_var(--border,_var(--color-globals-border-63))] rounded-full [background:var(--card,_var(--color-globals-background-64))] text-[var(--foreground,_var(--color-globals-color-65))] h-11 py-0 px-4 gap-2 text-[14px] whitespace-nowrap [&[data-connected='false']]:cursor-pointer"
      data-connected="false"
      onClick={() => router.push("/settings")}
    >
      {content}
    </button>
  );
}
